class OpenDotaApi
  def initialize
    @base_url = "https://api.opendota.com/api"
  end


  # GET /publicMatches
  def get_public_matches(min_rank:, max_rank:, less_than_match_id: nil)
    response = HTTParty.get("#{@base_url}/publicMatches?min_rank=#{min_rank}&max_rank=#{max_rank}#{less_than_match_id ? "&less_than_match_id=#{less_than_match_id}" : ''}")
    JSON.parse(response.body)
  end

  # [{
  # "match_id":8608845777,
  # "player_slot":130,
  # "radiant_win":true,
  # "duration":2671,
  # "game_mode":4,
  # "lobby_type":0,
  # "hero_id":102,
  # "start_time":1765957164,
  # "version":null,"kills":1,"deaths":7,"assists":13,"average_rank":75,"leaver_status":0,"party_size":null,"hero_variant":1},..]
  def get_player_matches(account_id:)
    id32 = self.class.steam64id_to_32id(steam64id: account_id)
    response = HTTParty.get("#{@base_url}/players/#{id32}/matches")
    JSON.parse(response.body)
  end

  def get_player(account_id:)
    id32 = self.class.steam64id_to_32id(steam64id: account_id)
    response = HTTParty.get("#{@base_url}/players/#{id32}")
    JSON.parse(response.body)
  end

