  def get_match_details(match_id:)
    if defined?(CachedMatchDetail)
      cached = CachedMatchDetail.find_by(match_id: match_id.to_s)
      return cached.payload if cached.present?
    end

    response = HTTParty.get("#{@base_url}/matches/#{match_id}")
    payload = JSON.parse(response.body)

    if defined?(CachedMatchDetail)
      CachedMatchDetail.find_or_initialize_by(match_id: match_id.to_s).update!(payload: payload)
    end

    payload
  end

  def download_replay(replay_url:, file_name: 'replay.dem')
    response = HTTParty.get(replay_url)
    File.binwrite(file_name, response.body)
  end

  # POST /request/{match_id}
  def request_parse(match_id:)
    response = HTTParty.post("#{@base_url}/request/#{match_id}")
    JSON.parse(response.body)
  end

  def self.steam64id_to_32id(steam64id:)
    steam64id.to_i - 76561197960265728
  end
